python3 - <<'PYEOF'
p = '/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature/tests/codegen/support/runner.rs'
s = open(p).read()
old = '''            // Drop the blank line php opens the diagnostic with, now that the diagnostic itself
            // is leaving: keeping it would leave a stray newline in the program's output.
            if program.ends_with('\\n') && program[..program.len() - 1].ends_with('\\n') {
                program.truncate(program.len() - 1);
            } else if program == "\\n" {
                program.clear();
            }'''
new = '''            // Drop the blank line php opens the diagnostic with, now that the diagnostic itself
            // is leaving. Exactly ONE newline, and without asking what precedes it: the program's
            // own output and that blank line share a line whenever the program did not end its
            // last write with a newline — `echo "false|"` followed by a warning arrives as the
            // single line `false|\\n`, and treating that newline as the program's left a stray
            // one behind.
            if program.ends_with('\\n') {
                program.truncate(program.len() - 1);
            }'''
assert old in s, "blank-line anchor not found"
s = s.replace(old, new, 1)
open(p, 'w').write(s)
print("blank-line handling corrected")
